//! The check that the code generated by `queryweave-derive` (or another crate
//! on `queryweave-codegen`) runs against a compatible runtime.

/// This crate's version, as `(major, minor)`.
const VERSION: (u64, u64) = (
    parse(env!("CARGO_PKG_VERSION_MAJOR")),
    parse(env!("CARGO_PKG_VERSION_MINOR")),
);

/// A version number, from its decimal digits.
const fn parse(digits: &str) -> u64 {
    let bytes = digits.as_bytes();
    let mut value = 0;
    let mut index = 0;
    while index < bytes.len() {
        value = value * 10 + (bytes[index] - b'0') as u64;
        index += 1;
    }
    value
}

/// Whether code generated by version `generator` runs against the runtime
/// version `runtime`. Before 1.0, every minor version may break: they must be
/// equal. From 1.0, the majors must be equal, and the runtime at least as new
/// as the generator (whose code may name items added since).
#[must_use]
pub const fn compatible(generator: (u64, u64), runtime: (u64, u64)) -> bool {
    let ((generator_major, generator_minor), (runtime_major, runtime_minor)) = (generator, runtime);
    if generator_major != runtime_major {
        return false;
    }
    if generator_major == 0 {
        generator_minor == runtime_minor
    } else {
        runtime_minor >= generator_minor
    }
}

/// Fail the build when the code generated by version `major.minor` of
/// `queryweave-codegen` names this runtime and they are not compatible
/// (`compatible`). Called by every derive's generated code, in a `const`.
///
/// # Panics
///
/// At compile time (in the `const` calling it), on an incompatible version,
/// naming the fix.
pub const fn require_version(major: u64, minor: u64) {
    assert!(
        compatible((major, minor), VERSION),
        "the queryweave derives and runtime crates have incompatible versions: use the same version of every queryweave crate (queryweave, queryweave-api, queryweave-sql, queryweave-derive, queryweave-codegen)"
    );
}

#[cfg(test)]
mod tests {
    use super::{VERSION, compatible, parse, require_version};

    #[test]
    fn test_parse_reads_decimal_digits() {
        assert_eq!(parse("0"), 0);
        assert_eq!(parse("17"), 17);
        assert_eq!(VERSION.0, parse(env!("CARGO_PKG_VERSION_MAJOR")));
    }

    // Before 1.0 the minor versions must match exactly.
    #[test]
    fn test_pre_1_0_versions_must_match() {
        assert!(compatible((0, 1), (0, 1)));
        assert!(!compatible((0, 1), (0, 2)));
        assert!(!compatible((0, 2), (0, 1)));
    }

    // From 1.0 the runtime may be newer, never older or of another major.
    #[test]
    fn test_post_1_0_runtime_may_be_newer() {
        assert!(compatible((1, 2), (1, 2)));
        assert!(compatible((1, 2), (1, 3)));
        assert!(!compatible((1, 3), (1, 2)));
        assert!(!compatible((1, 0), (2, 0)));
    }

    #[test]
    fn test_the_own_version_is_required_without_panicking() {
        require_version(VERSION.0, VERSION.1);
    }

    #[test]
    #[should_panic(expected = "incompatible versions")]
    fn test_another_version_panics() {
        require_version(VERSION.0, VERSION.1 + 1);
    }
}
